from flask import Flask, request, render_template_string
import subprocess

app = Flask(__name__)

@app.route("/colorize", methods=["POST"])
def colorize():
    text = request.form.get("text")

    colored = colorize_text(text)
    return render_template_string("<p>{{ colored }}</p>", colored=colored)

def colorize_text(text):
    color = text.split()[-1]
    color = color.replace("http://", "")
    color = color.replace("https://", "")
    hex_code = color

    try:
        rgb = subprocess.check_output(["hex2rgb", hex_code])
    except:
        return text

    return f"<a style='color:rgb({rgb})'>{text}</a>"

if __name__ == "__main__":
    app.run()

