class Tournament:
    def __init__(self, name: str, date: str, participants: List[str]):
        self.name = name
        self.date = date
        self.participants = participants
        self.score = {'nights': 0}

    def add_night(self):
        self.score['nights'] += 1

    @property
    def days(self):
        return self.score['nights'] // 24
        self.addToCorrectTrackAndDrainBoard()

def addToCorrectTrackAndDrainBoard(self):
    orbit_reservoir = self.score['nights'].copy()
    for day in orbit_reservoir:
        self.score['nights'] = day * 12

