import os
import re

url_regex = re.compile(r'^https?://[^/]+/(?:[^\s/]+/)*')

def check_url(url):
    if url_regex.match(url):
        return True

    if os.path.exists('/var/www/html/'):
        with open('/var/www/html/index.html', 'r') as f:
            index_html = f.read()
        if url in index_html:
            return True

    if os.path.exists('index.html'):
        with open('index.html', 'r') as f:
            html = f.read()
        if url in html:
            return True

    return False

