def lint_json(json_str):
    try:
        json.loads(json_str)
        return []
    except json.JSONDecodeError as e:
        errors = [{'message': str(e)}]
        if e.lineno:
            errors[0]['line'] = '# ' + e.filename + ':' + str(e.lineno)
        return errors

