import gmpy2

def dec2hex(number):
    return gmpy2.tobytes(number, 16).hex()

def calcChecksum(identity_number):
    dec = gmpy2.mpz(identity_number).convert()
    hex_id = dec2hex(dec)
    return hex_id[-8:]

