from heapq import heappush, heappop

def income(employees):
    avg_income = sum(employees) / len(employees)

    def get_next_lowest_income():
        lowest = min(employees)
        employees.remove(lowest)
        return lowest

    while employees:
        next_lowest = get_next_lowest_income()
        avg_income -= next_lowest
        if avg_income == 0:
            break

    return avg_income

